def txt(node):
    if isinstance(node,dict):
        if node.get('type')=='text': return node.get('text','')
        if 'inlineContent' in node: return ''.join(txt(c) for c in node['inlineContent'])
        if 'content' in node: return ''.join(txt(c) for c in node['content'])
        if node.get('type')=='codeVoice': return node.get('code','')
